-- Allow a Super Admin to record a final settlement above the accrued approved amount.
-- This is a positive payroll adjustment, not an employee debt or recoverable advance.
-- Existing payment history is never rewritten by this migration.
ALTER TABLE public."PayTeamSettlement"
  DROP CONSTRAINT IF EXISTS "PayTeamSettlement_paidTotal_check";

-- The original inline CHECK typically receives an autogenerated constraint name
-- from PostgreSQL: PayTeamSettlement_paidTotal_check. Verify below before migration
-- if your schema was modified manually.
ALTER TABLE public."PayTeamSettlement"
  ADD CONSTRAINT "PayTeamSettlement_paidTotal_positive" CHECK ("paidTotal" > 0);
